import * as DB from './db.js';
import {Collaboration,DEFAULT_PUBLIC_ROOM} from './collab.js';
import * as AI from './ai.js';

const APP_VERSION='5.0.0';
const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
const esc=v=>String(v??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const fmt=n=>Number(n||0).toLocaleString(undefined,{maximumFractionDigits:1});
const money=n=>Number(n||0).toLocaleString(undefined,{style:'currency',currency:'USD',maximumFractionDigits:0});
const dl=(name,text,type='text/plain')=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([text],{type}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1500)};
const state={texas:null,cross:null,partners:null,requirements:[],guides:[],route:'overview',presence:[],collabStatus:{mode:'offline',connected:false},prefs:{theme:localStorage.getItem('txco.theme')||'dark',contrast:localStorage.getItem('txco.contrast')==='1',motion:localStorage.getItem('txco.motion')!=='0',font:+localStorage.getItem('txco.font')||1,hud:localStorage.getItem('txco.hud')!=='0'}};

const ROUTES=[
 {id:'overview',label:'Overview',icon:'✦',group:'Start',top:true},
 {id:'diagnostics',label:'Diagnostic Lab',icon:'🧭',group:'Measure',top:true},
 {id:'broadband',label:'Broadband',icon:'◉',group:'Measure',top:true},
 {id:'affordability',label:'Affordability',icon:'$',group:'Measure'},
 {id:'devices',label:'Devices',icon:'▣',group:'Access'},
 {id:'skills',label:'Skills & Safety',icon:'⌘',group:'Access'},
 {id:'opportunity',label:'Opportunity',icon:'↗',group:'Opportunity',top:true},
 {id:'partners',label:'Institution & Family Matrix',icon:'🤝',group:'Opportunity'},
 {id:'education',label:'Education',icon:'🎓',group:'Opportunity'},
 {id:'health',label:'Health & Telehealth',icon:'🩺',group:'Opportunity'},
 {id:'workforce',label:'Workforce',icon:'🧰',group:'Opportunity'},
 {id:'business',label:'Small Business',icon:'🏪',group:'Opportunity'},
 {id:'libraries',label:'Libraries & Hubs',icon:'📚',group:'Opportunity'},
 {id:'emergency',label:'Emergency Comms',icon:'🚨',group:'Resilience'},
 {id:'infrastructure',label:'Infrastructure',icon:'🛠',group:'Plan'},
 {id:'mapping',label:'Mapping & Challenges',icon:'🗺',group:'Plan'},
 {id:'regions',label:'Texas Regions',icon:'★',group:'Plan'},
 {id:'projects',label:'Project Studio',icon:'◆',group:'Build',top:true},
 {id:'collaboration',label:'P2P Multiplayer Commons',icon:'◎',group:'Build',top:true},
 {id:'guides',label:'Simplified Advanced Guides',icon:'◈',group:'Build'},
 {id:'scenario',label:'Scenario Lab',icon:'∿',group:'Build'},
 {id:'funding',label:'Funding Navigator',icon:'▤',group:'Evidence'},
 {id:'research',label:'Research Library',icon:'🔎',group:'Evidence'},
 {id:'evidence',label:'Evidence Registry',icon:'✓',group:'Evidence'},
 {id:'ai',label:'Local AI / WebLLM',icon:'✺',group:'Advanced'},
 {id:'data',label:'Data & Backups',icon:'⬡',group:'Advanced'},
 {id:'atlas',label:'111-Section Atlas',icon:'☷',group:'Advanced'},
 {id:'about',label:'About / Integrity',icon:'ⓘ',group:'Advanced'}
];
const routeById=id=>ROUTES.find(r=>r.id===id)||ROUTES[0];

const collab=new Collaboration({
 onEvent:()=>{if(['collaboration','projects'].includes(state.route))render();updateHUD()},
 onPresence:p=>{state.presence=p;if(state.route==='collaboration')renderPresence();updateCollabBadge()},
 onStatus:s=>{state.collabStatus=s;updateCollabBadge();if(state.route==='collaboration')render()}
});

async function loadData(){
 const [t,c,p,r,g]=await Promise.all([fetch('./data/texas-current.json').then(x=>x.json()),fetch('./data/cross-domain.json').then(x=>x.json()),fetch('./data/partner-playbook.json').then(x=>x.json()),fetch('./data/requirements.json').then(x=>x.json()),fetch('./data/guides.json').then(x=>x.json())]);
 state.texas=t;state.cross=c;state.partners=p;state.requirements=r;state.guides=g;
}
function applyPrefs(){document.documentElement.dataset.theme=state.prefs.theme;document.documentElement.classList.toggle('high-contrast',state.prefs.contrast);document.documentElement.classList.toggle('reduce-motion',!state.prefs.motion);document.documentElement.style.setProperty('--font',state.prefs.font);$('#hud').hidden=!state.prefs.hud}
function savePrefs(){localStorage.setItem('txco.theme',state.prefs.theme);localStorage.setItem('txco.contrast',state.prefs.contrast?'1':'0');localStorage.setItem('txco.motion',state.prefs.motion?'1':'0');localStorage.setItem('txco.font',String(state.prefs.font));localStorage.setItem('txco.hud',state.prefs.hud?'1':'0');applyPrefs()}
function toast(msg){const t=$('#toast');t.textContent=msg;t.classList.add('show');clearTimeout(t._timer);t._timer=setTimeout(()=>t.classList.remove('show'),2600)}
function go(id){location.hash='#/'+id}
function currentRoute(){const id=location.hash.replace(/^#\/?/,'').split('/')[0]||'overview';return routeById(id).id}
function closeDrawer(){document.body.classList.remove('drawer-open');$('#drawerScrim').hidden=true}
function renderNav(){
 $('#topnav').innerHTML=ROUTES.filter(x=>x.top).map(r=>`<button data-route="${r.id}">${r.label}</button>`).join('');
 const groups=[...new Set(ROUTES.map(x=>x.group))];
 $('#sidenav').innerHTML=groups.map(g=>`<section class="navgroup"><h2>${esc(g)}</h2>${ROUTES.filter(r=>r.group===g).map(r=>`<button class="navlink" data-route="${r.id}"><span class="ico">${r.icon}</span><span>${esc(r.label)}</span></button>`).join('')}</section>`).join('');
 $$('[data-route]').forEach(b=>b.onclick=()=>{go(b.dataset.route);closeDrawer()});
}
function markActive(){$$('[data-route]').forEach(b=>b.classList.toggle('active',b.dataset.route===state.route));const r=routeById(state.route);$('#crumbs').textContent=`Texas Connectivity & Opportunity OS / ${r.group} / ${r.label}`}
function page(title,lede,inner,actions=''){return `<section class="hero"><div class="eyebrow">Texas Connectivity & Opportunity OS · ${esc(routeById(state.route).group)}</div><h1>${title}</h1><p class="lede">${lede}</p>${actions?`<div class="toolbar">${actions}</div>`:''}</section>${!navigator.onLine?'<div class="offlineBanner">Offline: saved tools and records remain available, but external sources, WebLLM downloads and hosted multiplayer may be unavailable or stale.</div>':''}${inner}`}
function tip(text,help){return `${esc(text)}<span class="tip" tabindex="0" role="note" aria-label="${esc(help)}" data-tip="${esc(help)}">?</span>`}
function card(title,body,cls=''){return `<article class="card ${cls}"><h2>${title}</h2>${body}</article>`}
function sourceCard(f){return `<article class="source"><div class="sourceTop"><div><span class="tag grade-${esc(f.grade)}">Evidence ${esc(f.grade)}</span><span class="tag">${esc(f.freshness)}</span></div><small class="muted">${esc(f.date)}</small></div><h3>${esc(f.title)}</h3><p><strong>${esc(f.value)}</strong></p><p class="small muted">${esc(f.note)}</p><p class="small">${esc(f.publisher)} · ${esc(f.jurisdiction)}</p><a href="${esc(f.url)}" target="_blank" rel="noopener noreferrer">Official source ↗</a></article>`}

function renderOverview(){
 const f=state.texas.facts;const bead=f.find(x=>x.id==='bead-summary'),boot=f.find(x=>x.id==='boot'),wf=f.find(x=>x.id==='workforce'),rh=f.find(x=>x.id==='rhcf');
 return page('Connectivity is an access layer for opportunity.','Measure the actual barrier, coordinate the right disciplines, connect projects to current Texas programs and evidence, and track work from observation through operational adoption.',`
 <div class="grid">
 ${card('Texas BEAD snapshot',`<div class="kpi">240k+</div><p>Broadband-serviceable locations in Texas' approved BEAD final-proposal snapshot, plus 2,700+ community anchor institutions.</p><p class="small muted">${esc(bead.note)}</p><a href="${bead.url}" target="_blank" rel="noopener">Official BDO source ↗</a>`)}
 ${card('BOOT deployment',`<div class="kpi">$633.8M</div><p>BOOT I + II awards stated on the current BDO program page.</p><p class="small muted">${esc(boot.value)}</p>`)}
 ${card('Broadband workforce',`<div class="kpi">2,800</div><p>Projected Texans trained through the $24.6M state broadband workforce program.</p><p class="small muted">${esc(wf.note)}</p>`)}
 ${card('Institutional connectivity',`<div class="kpi">124</div><p>Rural hospitals described in the 2025 CPF program report, spanning 113 counties.</p><p class="small muted">Infrastructure delivery and health outcomes are tracked separately.</p>`)}
 ${card('Public-library projects',`<div class="kpi">37</div><p>Public libraries receiving $4.107M in 2025–26 LIFI grants for broadband/facility improvements.</p><button class="btn" data-source="lifi">Open source</button>`)}
 ${card('E-Rate state match',`<div class="kpi">$5M</div><p>Maximum FY2026 Texas State Match Fund described by TEA for eligible E-Rate projects.</p><button class="btn" data-source="erate-match">Open source</button>`)}
 ${card('Seven-layer diagnostic',`<div class="flow"><span>Access</span><b>+</b><span>Affordability</span><b>+</b><span>Devices</span><b>+</b><span>Skills</span><b>+</b><span>Reliability</span><b>+</b><span>Safety</span><b>+</b><span>Useful Services</span></div><p>Deployment alone is not treated as inclusion.</p><button class="btn primary" data-jump="diagnostics">Run diagnostic</button>`,'wide')}
 ${card('Decentralized collaboration',`<p><strong>Local commons:</strong> BroadcastChannel synchronizes same-device tabs.</p><p><strong>P2P rooms:</strong> Trystero discovers peers through decentralized signaling and WebRTC carries shared work directly browser-to-browser.</p><p class="small muted">No account is required by this app. On hosted/online startup the OS auto-joins the shared public Texas commons using Nostr discovery; only records explicitly created/shared in that room are synchronized. Leave the room at any time.</p><button class="btn" data-jump="collaboration">Open P2P commons</button>`)}
 ${card('Evidence discipline',`<p>Every sourced Texas fact carries a publisher, date, jurisdiction, evidence class, freshness state, limitations and official link.</p><div class="chips"><span class="tag grade-A">A official</span><span class="tag">C institutional</span><span class="tag grade-E">E modeled</span><span class="tag grade-F">F proposal</span></div><button class="btn" data-jump="evidence">Inspect evidence</button>`)}
 ${card('Cross-domain handoffs',`<div class="domainGrid">${state.cross.domains.slice(0,6).map(d=>`<div class="item"><strong>${d.icon} ${esc(d.name)}</strong><div class="small muted">${esc(d.handoffs[0])}</div></div>`).join('')}</div><p><button class="btn" data-jump="opportunity">Explore dependency graph</button></p>`,'full')}
 </div>`,`<button class="btn primary" data-jump="projects">Create project</button><button class="btn" data-jump="collaboration">Start team room</button><button class="btn" data-jump="research">Open current sources</button>`)}

function renderDiagnostics(){return page('Connectivity diagnostic lab','Separate infrastructure gaps from affordability, device, skills, reliability, accessibility and relevance barriers before selecting an intervention.',`
 <div class="grid">
 ${card('Household / site self-assessment',`<form id="diagForm" class="formgrid"><div class="field"><label>Monthly internet cost ($)</label><input name="cost" type="number" min="0" value="80"></div><div class="field"><label>Monthly household income ($)</label><input name="income" type="number" min="0" value="4000"></div><div class="field"><label>Advertised download Mbps</label><input name="advDown" type="number" min="0" value="300"></div><div class="field"><label>Measured download Mbps</label><input name="down" type="number" min="0" value="150"></div><div class="field"><label>Measured upload Mbps</label><input name="up" type="number" min="0" value="20"></div><div class="field"><label>Latency ms</label><input name="latency" type="number" min="0" value="35"></div><div class="field"><label>Outages per month</label><input name="outages" type="number" min="0" value="1"></div><div class="field"><label>Adequate computers/tablets</label><select name="device"><option value="yes">Yes</option><option value="shared">Shared / constrained</option><option value="no">No</option></select></div><div class="field"><label>Digital skill confidence</label><select name="skills"><option value="high">High</option><option value="medium">Some support needed</option><option value="low">Substantial support needed</option></select></div><div class="field"><label>Accessibility barriers</label><select name="access"><option value="no">None identified</option><option value="yes">Yes / uncertain</option></select></div><div class="span2 actions"><button class="btn primary" type="submit">Diagnose</button></div></form><div id="diagResult"></div>`,'wide')}
 ${card('Interpretation guardrails',`<ul><li>Measured speed depends on device, Wi-Fi, congestion and test conditions.</li><li>FCC availability mapping is not a performance, affordability or adoption measure.</li><li>A diagnostic flags likely bottlenecks; it is not ISP-level fault isolation.</li><li>Precise location is never requested automatically.</li></ul>`)}
 ${card('Bandwidth estimator',`<form id="bwForm" class="formgrid"><div class="field"><label>HD video streams</label><input name="hd" type="number" min="0" value="2"></div><div class="field"><label>4K streams</label><input name="k4" type="number" min="0" value="1"></div><div class="field"><label>Video calls</label><input name="calls" type="number" min="0" value="2"></div><div class="field"><label>Cloud gaming</label><input name="gaming" type="number" min="0" value="0"></div><div class="field"><label>Online classes</label><input name="classes" type="number" min="0" value="1"></div><div class="field"><label>Heavy uploads/backups</label><input name="uploads" type="number" min="0" value="1"></div><div class="span2 actions"><button class="btn" type="submit">Estimate</button></div></form><div id="bwResult"></div>`,'half')}
 ${card('Router + modem backup runtime',`<form id="powerForm" class="formgrid"><div class="field"><label>Battery usable Wh</label><input name="wh" type="number" min="0" value="300"></div><div class="field"><label>Router watts</label><input name="router" type="number" min="0" value="12"></div><div class="field"><label>Modem/ONT watts</label><input name="modem" type="number" min="0" value="10"></div><div class="field"><label>Other network watts</label><input name="other" type="number" min="0" value="0"></div><div class="field"><label>Efficiency %</label><input name="eff" type="number" min="1" max="100" value="85"></div><div class="span2 actions"><button class="btn" type="submit">Estimate runtime</button></div></form><div id="powerResult"></div>`,'half')}
 </div>`)}

function renderBroadband(){return page('Broadband performance & reliability','Log observed performance locally, compare advertised and measured service, and separate recurring user observations from verified provider availability.',`
 <div class="grid">
 ${card('Speed-test log',`<form id="speedForm" class="formgrid"><div class="field"><label>Provider</label><input name="provider" required></div><div class="field"><label>Connection</label><select name="connection"><option>Wi-Fi</option><option>Ethernet</option><option>Mobile</option></select></div><div class="field"><label>Download Mbps</label><input name="down" type="number" step=".1" required></div><div class="field"><label>Upload Mbps</label><input name="up" type="number" step=".1" required></div><div class="field"><label>Latency ms</label><input name="latency" type="number" step=".1" required></div><div class="field"><label>Location category</label><select name="place"><option>Home</option><option>School</option><option>Library</option><option>Clinic</option><option>Business</option><option>Public Wi-Fi</option></select></div><div class="span2 actions"><button class="btn primary" type="submit">Save locally</button><button class="btn" type="button" id="speedCsv">Export CSV</button></div></form>`,'half')}
 ${card('Reliability event',`<form id="outageForm" class="formgrid"><div class="field"><label>Type</label><select name="kind"><option>Outage</option><option>Slowdown</option><option>Packet loss</option><option>Intermittent</option></select></div><div class="field"><label>Duration minutes</label><input name="minutes" type="number" min="0" value="30"></div><div class="field span2"><label>Observation</label><textarea name="note"></textarea></div><div class="span2"><button class="btn" type="submit">Record event</button></div></form>`,'half')}
 ${card('Recent speed observations',`<canvas id="speedChart" class="chart" width="900" height="240" aria-label="Speed log chart"></canvas><div id="speedList" class="list"></div>`,'wide')}
 ${card('Technology explainer',`<div class="list"><div class="item"><strong>Fiber</strong><div class="small muted">Very high capacity and scalable; civil construction and drops can dominate deployment cost.</div></div><div class="item"><strong>Fixed wireless</strong><div class="small muted">Can accelerate coverage where suitable spectrum, backhaul and radio paths exist; terrain/vegetation/interference matter.</div></div><div class="item"><strong>Mobile broadband</strong><div class="small muted">Performance varies by signal, spectrum, congestion, device and indoor conditions.</div></div><div class="item"><strong>Satellite</strong><div class="small muted">Can reach difficult geographies; installation, obstruction, weather, capacity and service policies matter.</div></div></div>`)}
 ${card('Official mapping distinction',`<p>The FCC National Broadband Map shows provider-reported <strong>availability</strong>, not network performance, affordability or adoption.</p><button class="btn" data-jump="mapping">Open challenge workflow</button>`,'full')}
 </div>`)}

function renderAffordability(){return page('Affordability & total digital cost','Model broadband burden and the full annual cost of participation without assuming that availability means a household can afford service.',`
 <div class="grid">${card('Broadband burden calculator',`<form id="affForm" class="formgrid"><div class="field"><label>Internet / month</label><input name="internet" type="number" value="80"></div><div class="field"><label>Household income / month</label><input name="income" type="number" value="4000"></div><div class="field"><label>Mobile / month</label><input name="mobile" type="number" value="90"></div><div class="field"><label>Software / month</label><input name="software" type="number" value="20"></div><div class="field"><label>Device cost / year</label><input name="devices" type="number" value="500"></div><div class="field"><label>Repairs/accessories / year</label><input name="repairs" type="number" value="200"></div><div class="span2"><button class="btn primary" type="submit">Calculate</button></div></form><div id="affResult"></div>`,'wide')}${card('Interpretation',`<p><strong>Broadband burden = monthly internet cost ÷ monthly household income × 100.</strong></p><p>This is a transparent ratio, not an official eligibility rule. The OS does not impose a universal affordability threshold because household circumstances differ.</p><p>Compare with public-access, mobile, fixed-wireless and other options by actual total cost and suitability.</p>`)}${card('Adoption-gap decomposition',`<div class="flow"><span>Availability</span><b>≠</b><span>Affordability</span><b>≠</b><span>Device</span><b>≠</b><span>Skills</span><b>≠</b><span>Trust / relevance</span></div><p>Projects should name the barrier they are designed to change.</p>`,'full')}</div>`)}

function renderDevices(){return page('Device access & lifecycle','Inventory devices locally, identify task-specific bottlenecks, and support secure refurbishment without bypassing activation locks or security controls.',`
 <div class="grid">${card('Add device',`<form id="deviceForm" class="formgrid"><div class="field"><label>Device</label><input name="name" placeholder="Laptop 1" required></div><div class="field"><label>Type</label><select name="type"><option>Laptop</option><option>Desktop</option><option>Tablet</option><option>Smartphone</option><option>Accessibility device</option></select></div><div class="field"><label>OS</label><input name="os"></div><div class="field"><label>Battery health / condition</label><input name="battery"></div><div class="field"><label>Storage</label><input name="storage"></div><div class="field"><label>Primary use</label><input name="use" placeholder="School / work / telehealth"></div><div class="span2"><button class="btn primary">Save device</button></div></form>`,'half')}${card('Refurbishment chain',`<div class="flow"><span>Donate</span><b>→</b><span>Inspect</span><b>→</b><span>Secure wipe</span><b>→</b><span>Repair</span><b>→</b><span>Reinstall</span><b>→</b><span>Test</span><b>→</b><span>Distribute</span><b>→</b><span>Support</span></div><ul><li>Record donor/provenance without retaining unnecessary personal data.</li><li>Use vendor/platform-approved reset and wipe methods.</li><li>Do not bypass activation locks, MDM or anti-theft controls.</li><li>Document OS/security-update status before distribution.</li></ul>`,'half')}${card('Local device inventory','<div id="deviceList" class="list"></div>','full')}</div>`)}

function renderSkills(){return page('Digital skills, information literacy & cyber safety','Treat skills and safety as infrastructure: people need usable devices, confidence, support, accessible services and recovery procedures—not only a connection.',`
 <div class="grid">${card('Core digital literacy',`<ul><li>Browser/navigation and downloads</li><li>Email and account recovery</li><li>Documents, spreadsheets and file management</li><li>Video calls and accessibility settings</li><li>Cloud concepts and backups</li></ul>`)}${card('Information & AI literacy',`<ul><li>Check publisher, date, evidence and source chain.</li><li>Distinguish reporting, analysis, inference and marketing.</li><li>Generative AI can hallucinate: verify consequential facts.</li><li>Avoid pasting secrets or sensitive household data into unfamiliar AI services.</li><li>Use local AI where feasible for privacy-sensitive planning.</li></ul>`)}${card('Cyber safety',`<ul><li>Password manager + unique passwords</li><li>MFA/passkeys where available</li><li>Phishing/scam recognition</li><li>Software/firmware updates</li><li>Backups and account-recovery planning</li><li>Public Wi-Fi: prefer HTTPS and use appropriate risk controls; public Wi-Fi is not automatically unsafe.</li></ul>`)}${card('Accessibility',`<p>Plan for screen readers, captions, voice control, magnification, keyboard-only operation, cognitive load and large touch targets.</p><p>Texas DIR maintains public-sector digital accessibility guidance; regulated entities should consult current requirements.</p><button class="btn" data-source="accessibility">View source</button>`,'full')}</div>`)}

function domainView(id){const d=state.cross.domains.find(x=>x.id===id);return page(`${d.icon} ${d.name}`,d.dependency,`<div class="grid">${card('Stakeholders',`<div class="chips">${d.stakeholders.map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><p>Use the Multiplayer Commons to assign roles and keep domain-specific assumptions visible.</p><button class="btn" data-jump="collaboration">Coordinate</button>`,'half')}${card('Shared metrics',`<ul>${d.sharedMetrics.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`,'half')}${card('Cross-domain handoffs',`<div class="list">${d.handoffs.map(x=>`<div class="item">${esc(x)}</div>`).join('')}</div>`,'half')}${card('Relevant evidence',`<div class="list">${factsForDomain(id).map(f=>`<div class="item"><strong>${esc(f.title)}</strong><div class="small muted">${esc(f.value)}</div><a href="${f.url}" target="_blank" rel="noopener">Official source ↗</a></div>`).join('')||'<p class="muted">Use the evidence registry and add locally verified sources.</p>'}`,'half')}</div>`)}
function factsForDomain(id){const map={education:['erate','libraries','accessibility'],health:['rhcf','accessibility'],workforce:['workforce','training'],business:['smallbiz','acs'],libraries:['libraries','lifi','erate','digital-opportunity'],emergency:['emergency','dir-telecom'],government:['accessibility','digital-opportunity'],agriculture:['tx-map'],energy:['emergency','tx-map'],water:['emergency'],mobility:['accessibility'],};return state.texas.facts.filter(f=>(map[id]||[]).includes(f.id))}
function renderOpportunity(){return page('Cross-domain opportunity graph','Connectivity creates value through services and institutions. Use dependency handoffs to design projects jointly rather than pushing broadband work into a silo.',`<div class="domainGrid">${state.cross.domains.map(d=>`<article class="domainCard"><h3>${d.icon} ${esc(d.name)}</h3><p class="small muted">${esc(d.dependency)}</p><div class="chips">${d.handoffs.slice(0,2).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><button class="btn" data-domain="${d.id}">Open domain</button></article>`).join('')}</div><div class="grid">${card('Opportunity cascade',`<div class="flow"><span>Connectivity</span><b>→</b><span>Information access</span><b>→</b><span>Education</span><b>→</b><span>Skills</span><b>→</b><span>Employment opportunity</span><b>→</b><span>Household stability</span></div><p class="small muted">This is a pathway model. It does not claim guaranteed causation at each step.</p>`,'full')}</div>`)}

function renderPartners(){const sectors=state.partners?.sectors||[];return page('Institution, business & family collaboration matrix','Translate participation into concrete inputs, outputs and handoffs. A named partner is not treated as implementation unless an owner, requested contribution and verification step are recorded.',`<div class="callout"><strong>Shared protocol:</strong> ${esc((state.partners?.principles||[]).join(' · '))}</div><div class="domainGrid">${sectors.map(s=>`<article class="domainCard"><h3>${s.icon} ${esc(s.name)}</h3><p>${esc(s.mission)}</p><details><summary>Can contribute</summary><ul>${s.canContribute.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><details><summary>Needs from collaborators</summary><ul>${s.needsFromOthers.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><details><summary>Typical handoffs</summary><ul>${s.typicalHandoffs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details><button class="btn" data-jump="collaboration">Open multidisciplinary room</button></article>`).join('')}</div><div class="grid">${card('Minimum handoff packet',`<ol><li>From/to discipline or organization type</li><li>Requested contribution</li><li>Geography/site/project</li><li>Why the handoff is needed</li><li>Evidence or source references</li><li>Owner and due date</li><li>Privacy classification</li><li>Status and verification criterion</li></ol>`,'half')}${card('Data boundary',`<p>Peer rooms are for project coordination, not protected case management. Keep credentials, protected health/student records, precise sensitive household data and regulated confidential records in approved systems.</p><p>Use references or aggregate facts in the commons when detailed records must stay elsewhere.</p>`,'half')}</div>`) }


function renderEmergency(){return page('Emergency connectivity & continuity','Design primary, alternate and contingency communications around real dependencies: network infrastructure, power, warning systems, staff procedures and public access.',`<div class="grid">${card('Continuity checklist',`<ul><li>Identify primary ISP/mobile/warning channel.</li><li>Name an alternate channel with different failure modes where feasible.</li><li>Estimate router/modem/ONT/tower-site power dependencies.</li><li>Keep critical contact lists and procedures available offline.</li><li>Define shelter/library/community-hub public connectivity.</li><li>Exercise the plan and record findings.</li></ul><button class="btn" data-jump="diagnostics">Runtime calculator</button>`,'half')}${card('Texas precedent',`<p>TDEM's April 2026 statewide drill asked local alerting authorities to exercise primary, alternate and contingency warning systems and report findings.</p><p>This OS is a planning/coordination layer and does not replace official alerting systems.</p><button class="btn" data-source="emergency">Official source</button>`,'half')}${card('Critical infrastructure handoffs',`<div class="flow"><span>Grid outage</span><b>→</b><span>network power</span><b>→</b><span>warning/telehealth/work/school disruption</span><b>→</b><span>alternate links + public hubs + offline procedures</span></div>`,'full')}</div>`)}

function renderInfrastructure(){return page('Infrastructure planning','Compare fiber, fixed wireless, mobile, satellite, public Wi-Fi and middle-mile/last-mile dependencies using explicit assumptions—not one-size-fits-all technology claims.',`
 <div class="grid">${card('Simplified cost model',`<form id="infraForm" class="formgrid"><div class="field"><label>Route distance (miles)</label><input name="miles" type="number" value="10"></div><div class="field"><label>Premises</label><input name="premises" type="number" value="500"></div><div class="field"><label>Planning cost / route mile</label><input name="mileCost" type="number" value="40000"></div><div class="field"><label>Premise/drop allowance</label><input name="dropCost" type="number" value="1200"></div><div class="field"><label>Backhaul/site allowance</label><input name="backhaul" type="number" value="150000"></div><div class="field"><label>Contingency %</label><input name="cont" type="number" value="20"></div><div class="span2"><button class="btn primary">Estimate</button></div></form><div id="infraResult"></div><p class="small muted">Planning estimate only. Actual design, make-ready, permitting, rights-of-way, labor, materials, terrain and backhaul can materially differ.</p>`,'wide')}${card('Project pipeline',`<div class="flow"><span>Need</span><b>→</b><span>Feasibility</span><b>→</b><span>Funding</span><b>→</b><span>Engineering</span><b>→</b><span>Permitting</span><b>→</b><span>Construction</span><b>→</b><span>Activation</span><b>→</b><span>Adoption</span></div><p>Never collapse “awarded” into “operational.”</p>`)}${card('Texas planning requirements',`<p>BDO planning guidance emphasizes project area, technology, route distance, locations served, costs, cost per location, speed/latency and local collaboration.</p><button class="btn" data-source="tx-map">Mapping source</button>`,'full')}</div>`)}

function renderMapping(){const f=state.texas.facts.find(x=>x.id==='fcc-map');return page('Mapping, evidence & challenge workflow','Use official availability maps as one evidence layer, then add measured performance and local observations without mislabeling community reports as verified coverage.',`<div class="grid">${card('FCC availability challenge',`<div class="flow"><span>Observe discrepancy</span><b>→</b><span>Document evidence</span><b>→</b><span>Submit official challenge</span><b>→</b><span>Track status</span></div><p>${esc(f.value)}.</p><a href="${f.url}" target="_blank" rel="noopener">FCC challenge instructions ↗</a>`,'wide')}${card('Evidence separation',`<ul><li><strong>Availability:</strong> provider-reported map layer.</li><li><strong>Performance:</strong> measured tests with conditions.</li><li><strong>Reliability:</strong> outage/slowdown observations.</li><li><strong>Adoption:</strong> household subscription/use measures.</li><li><strong>Affordability:</strong> price/income burden or plan comparisons.</li></ul>`)}${card('Texas map',`<p>The BDO Texas Broadband Development Map uses FCC BDC data and the state map definition described in the current BDO mapping page.</p><button class="btn" data-source="tx-map">Official BDO mapping page</button>`,'full')}</div>`)}

const regionNotes={
 'Panhandle':'Long distances and dispersed premises can increase middle-mile/last-mile economics; model fiber and wireless backhaul explicitly.',
 'West Texas':'Sparse settlement, oil/gas/agriculture operations and long transport corridors can create mixed residential/industrial connectivity requirements.',
 'Permian Basin':'Industrial telemetry, workforce housing and emergency communications create cross-domain demand beyond household broadband.',
 'Rio Grande Valley':'Household affordability, education/workforce access, health services and dense/rural edge conditions should be analyzed separately by locality.',
 'Gulf Coast':'Hurricane/flood exposure makes power and communications continuity a first-class requirement for hubs and critical services.',
 'East Texas':'Forested terrain can affect radio paths; communities should compare wired and wireless designs using local surveys and engineering.',
 'Central Texas':'Rapid growth can create construction, right-of-way, capacity and affordability pressures at different scales.',
 'North Texas':'Metro growth and rural fringes require separating high-capacity urban demand from unserved/underserved edge cases.',
 'Rural Texas':'Do not treat “rural” as one topology; premise density, backhaul, terrain, income, institutions and incumbent networks vary widely.'
};
function renderRegions(){return page('Texas regional planning profiles','Texas is not one connectivity environment. These are planning prompts—not measured county profiles—designed to force local evidence collection before a project is chosen.',`<div class="domainGrid">${Object.entries(regionNotes).map(([k,v])=>`<article class="domainCard"><h3>${esc(k)}</h3><p>${esc(v)}</p><button class="btn" data-prefill-region="${esc(k)}">Start project</button></article>`).join('')}</div><div class="callout warn">For an actual county profile, attach current FCC/BDO/Census/local planning data and record the retrieval date. The suite deliberately avoids inventing county statistics.</div>`)}

function projectForm(prefill=''){return `<form id="projectForm" class="formgrid"><div class="field"><label>Project title</label><input name="title" required value="${esc(prefill)}"></div><div class="field"><label>Geography</label><input name="geography" placeholder="County / city / region"></div><div class="field span2"><label>Problem statement</label><textarea name="problem" required placeholder="What barrier is being changed?"></textarea></div><div class="field"><label>Population / premises</label><input name="population" placeholder="e.g., 1,200 premises"></div><div class="field"><label>Intervention</label><input name="intervention" placeholder="fiber / public Wi-Fi / device bank / skills / hybrid"></div><div class="field"><label>Capital estimate ($)</label><input name="capital" type="number" min="0"></div><div class="field"><label>Annual operating estimate ($)</label><input name="operating" type="number" min="0"></div><div class="field"><label>Timeline</label><input name="timeline" placeholder="12 months"></div><div class="field"><label>Status</label><select name="status"><option>Proposed</option><option>Validated</option><option>Funding</option><option>Engineering</option><option>Building</option><option>Operational</option><option>Adoption</option></select></div><div class="field"><label>${tip('Lead sector','The sector accountable for coordinating this project. This label does not grant permissions.')}</label><select name="leadSector"><option value="">Choose…</option>${(state.partners?.sectors||[]).map(s=>`<option value="${s.id}">${esc(s.name)}</option>`).join('')}</select></div><div class="field"><label>Primary success metric</label><input name="successMetric" placeholder="e.g., activated premises / outage minutes / completed training"></div><div class="field span2"><label>Partners</label><input name="partners" placeholder="library, clinic, county, ISP, school, employer, families..."></div><div class="field"><label>${tip('Privacy class','Public = safe to publish; Internal = organization work product; Sensitive = do not place detailed data in open peer rooms.')}</label><select name="privacyClass"><option>Public</option><option>Internal</option><option>Sensitive — references only</option></select></div><div class="field"><label>Verification date</label><input name="verificationDate" type="date"></div><div class="field span2"><label>Evidence / verification plan</label><textarea name="evidence"></textarea></div><div class="span2"><div class="small muted">Cross-domain tags</div><div class="matrix" id="domainMatrix">${state.cross.domains.map(d=>`<button type="button" data-domain-tag="${d.id}">${d.icon} ${esc(d.name)}</button>`).join('')}</div></div><div class="span2 actions"><button class="btn primary">Create project</button></div></form>`}
function renderProjects(){return page('Cross-domain project studio','Create projects with explicit status, dependencies, partners, evidence and domain tags. New projects can be broadcast into the current collaboration room.',`<div class="grid">${card('Project generator',projectForm(),'wide')}${card('Prioritization dimensions',`<ul><li>people/premises served</li><li>affordability improvement</li><li>reliability and resilience</li><li>implementation time</li><li>rural reach</li><li>education/health/workforce opportunity</li><li>maintenance and operating burden</li></ul><p>Do not hide weights behind a “best project” score. Use the scenario lab to expose assumptions.</p>`)}${card('Saved/shared projects','<div id="projectList" class="list"></div>','full')}</div>`)}

function renderCollaboration(){const roles=state.cross.collaborationRoles;const isPublic=collab.room===DEFAULT_PUBLIC_ROOM;return page('Decentralized P2P Multiplayer Commons','The hosted OS automatically joins a shared public Texas commons when online. Trystero handles decentralized peer discovery and WebRTC carries shared room traffic directly browser-to-browser; BroadcastChannel provides a same-device fallback.',`
 <div class="callout ${isPublic?'warn':''}"><strong>${isPublic?'Public commons active':'Private/custom room'}</strong> · ${isPublic?`Room <code>${esc(DEFAULT_PUBLIC_ROOM)}</code> is the default startup commons. Display name, role and ephemeral peer/client identifiers are self-asserted and <strong>not verified identities</strong>. Only records explicitly created/shared in this room are synchronized; room snapshots are scoped to this room.`:'Use a hard-to-guess room ID and optional shared password for non-public collaboration. Records remain scoped to the room in which they were shared.'}</div>
 <div class="grid">${card('Room connection',`<form id="roomForm" class="formgrid"><div class="field"><label>${tip('Display name','A self-asserted local display label shared with peers. It is not identity verification. Avoid sensitive personal data.')}</label><input name="name" value="${esc(collab.name)}"></div><div class="field"><label>${tip('Disciplinary role','A self-asserted coordination label that makes responsibilities visible. It grants no permissions and does not verify employment, credentials or institutional affiliation.')}</label><select name="role">${roles.map(r=>`<option value="${r.id}" ${collab.role===r.id?'selected':''}>${esc(r.label)}</option>`).join('')}</select></div><div class="field"><label>${tip('Room ID','The default public room is shared by all hosted users. For private/custom work, choose a hard-to-guess room ID; peers must use exactly the same value.')}</label><input name="room" value="${esc(collab.room)}"></div><div class="field"><label>${tip('Discovery strategy','Trystero uses the selected decentralized discovery network to help browsers find peers and exchange WebRTC session information. Project/task/comment/decision/state traffic then moves over WebRTC.')}</label><select name="strategy"><option value="nostr">Nostr — default / decentralized</option><option value="mqtt">MQTT — public broker discovery</option><option value="torrent">BitTorrent tracker discovery</option><option value="ipfs">IPFS discovery</option></select></div><div class="field span2"><label>${tip('Optional shared room password','A shared secret passed to Trystero so session-description encryption derives from the shared password. It is not institutional identity/access management. Every peer must use the same password.')}</label><input name="password" type="password" autocomplete="new-password" placeholder="Optional — share out-of-band"></div><div class="field span2"><label>${tip('Optional TURN fallback','TURN is only a fallback relay for networks where peers cannot establish a direct WebRTC path. It is not hidden infrastructure. Enter a JSON array of RTCIceServer objects only when needed; WebRTC encryption remains in use but traffic may traverse the relay.')}</label><textarea name="turnJson" rows="3" placeholder='[ {"urls":["turn:turn.example.org:3478"],"username":"…","credential":"…"} ]'></textarea></div><div class="span2 actions"><button class="btn" type="button" id="rejoinPublic">Rejoin default public room</button><button class="btn" type="button" id="localRoom">Same-device local room</button><button class="btn primary" type="submit">Join selected P2P room</button><button class="btn" type="button" id="copyRoom">Copy non-secret room settings</button><button class="btn" type="button" id="disconnectRoom">Leave room</button></div></form><p class="small muted">Mode: <strong>${esc(state.collabStatus.mode)}</strong> · ${state.collabStatus.connected?'active':'not connected'}${state.collabStatus.peerCount!=null?` · ${state.collabStatus.peerCount} remote peers`:''}. Trystero 0.25.3 is pinned and loaded on demand. ${isPublic?'Public-room sharing rejects records marked Internal/Sensitive and keeps them local-only.':''}</p>`,'wide')}${card('How peer networking works',`<div class="advancedGuide"><div><h3>Plain language</h3><p>Your browser finds other browsers in the same room, then exchanges shared work directly with them. The default public commons auto-connects when possible; private rooms remain available.</p></div><div><h3>Advanced</h3><p>Trystero performs decentralized discovery/signaling; WebRTC DataChannels carry serialized actions. Every browser keeps its own IndexedDB copy. When a participant joins, existing peers can send a room-scoped snapshot of projects, tasks, comments, decisions, evidence and handoffs.</p></div><div class="expert"><h3>Expert / implementation detail</h3><p>Snapshot and event records are tagged with <code>collaborationRoom</code>, preventing state from one room from being sent into another. Direct WebRTC can fail across some enterprise/mobile NAT/firewall combinations; an explicitly configured TURN relay is the documented fallback rather than invisible infrastructure.</p></div></div><p><button class="btn" data-jump="guides">Open Simplified Advanced Guides</button></p>`)}
 ${card('Ephemeral presence',`<div id="presence" class="presence"></div><p class="small muted">${tip('Peer identity warning','Peer/client IDs are transport identifiers. Display names, roles and organization labels are self-asserted. This OS does not verify that a peer is the human, company, agency, school, institution or credential-holder they claim to be.')} Presence expires automatically and is not an institutional identity system.</p>`)}
 ${card('New shared task',`<form id="taskForm" class="formgrid"><div class="field span2"><label>Task</label><input name="title" required></div><div class="field"><label>Domain</label><select name="domain">${state.cross.domains.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></div><div class="field"><label>Assignee</label><input name="assignee" placeholder="name / organization"></div><div class="field"><label>Due</label><input name="due" type="date"></div><div class="field"><label>Lane</label><select name="status"><option>Backlog</option><option>Doing</option><option>Blocked</option><option>Done</option></select></div><div class="span2"><button class="btn primary">Add task</button></div></form>`,'half')}
 ${card('Record decision',`<form id="decisionForm" class="formgrid"><div class="field span2"><label>Decision</label><input name="title" required></div><div class="field span2"><label>Rationale / constraints</label><textarea name="rationale"></textarea></div><div class="field"><label>Status</label><select name="status"><option>Proposed</option><option>Accepted</option><option>Deferred</option><option>Revisit</option></select></div><div class="field"><label>Evidence refs</label><input name="evidence" placeholder="source IDs / links"></div><div class="span2"><button class="btn">Record decision</button></div></form>`,'half')}
 ${card('Shared task board','<div id="taskBoard" class="kanban"></div>','full')}${card('Decision log','<div id="decisionList" class="list"></div>','half')}${card('Comment / coordination note',`<form id="commentForm"><div class="field"><label>Note</label><textarea name="text" required></textarea></div><div class="actions"><button class="btn">Share note</button></div></form><div id="commentList" class="timeline"></div>`,'half')}${card('Cross-domain handoff',`<form id="handoffForm" class="formgrid"><div class="field"><label>${tip('From discipline','The team or sector requesting another discipline’s contribution.')}</label><select name="fromDomain">${state.cross.domains.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></div><div class="field"><label>${tip('To discipline','The domain expected to own or respond to the requested contribution.')}</label><select name="toDomain">${state.cross.domains.map(d=>`<option value="${d.id}">${esc(d.name)}</option>`).join('')}</select></div><div class="field span2"><label>Requested contribution</label><textarea name="request" required placeholder="What do you need this discipline/organization to provide or decide?"></textarea></div><div class="field"><label>Owner / organization</label><input name="owner" placeholder="person, team or organization"></div><div class="field"><label>Due</label><input name="due" type="date"></div><div class="field"><label>Status</label><select name="status"><option>Requested</option><option>Acknowledged</option><option>In progress</option><option>Blocked</option><option>Completed</option><option>Verified</option></select></div><div class="field"><label>${tip('Privacy class','Public records can be shared in the default commons. Internal/Sensitive records are kept local-only while you are in the public room; use an approved private room/system for protected work.')}</label><select name="privacyClass"><option>Public</option><option>Internal</option><option>Sensitive — references only</option></select></div><div class="field span2"><label>Evidence / context refs</label><input name="evidence" placeholder="source IDs, project IDs, public links"></div><div class="span2"><button class="btn primary">Create handoff</button></div></form>`,'half')}${card('Handoff board','<div id="handoffList" class="list"></div>','full')}</div>`)}
function renderPresence(){const p=$('#presence');if(!p)return;p.innerHTML=state.presence.map(m=>`<span class="person ${m.clientId===collab.clientId?'self':''}" title="Self-asserted presence; identity is not verified">${esc(m.name)} · ${esc(m.role)} · unverified</span>`).join('')||'<span class="muted">No active room presence yet.</span>'}

function renderGuides(){return page('Simplified Advanced Guides','Each guide follows the same learning ladder: one-minute explanation → actionable steps → advanced explanation → expert / implementation detail. Expand only as far as you need, then use the verification and cross-domain handoff sections to turn learning into accountable work.',`<div class="guideDeck">${state.guides.map(g=>`<details class="guide" id="guide-${g.id}"><summary>${esc(g.title)} <span class="tag">${esc(g.audience)}</span></summary><div class="guideBody"><div class="guideQuick"><strong>One-minute explanation</strong><p>${esc(g.quick)}</p></div><div class="level"><h3>Actionable steps</h3><ol>${g.steps.map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div><div class="advancedGuide"><div><h3>Advanced explanation</h3><p>${esc(g.advanced)}</p></div><div class="expert"><h3>Expert / implementation detail</h3><p>${esc(g.expert)}</p></div></div>${g.pitfalls?.length?`<div class="level"><h3>Common failure modes</h3><ul>${g.pitfalls.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${g.handoffs?.length?`<div class="level"><h3>Cross-domain handoffs</h3><ul>${g.handoffs.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`:''}${g.verification?`<div class="level"><h3>Verification</h3><p>${esc(g.verification)}</p></div>`:''}</div></details>`).join('')}</div>`)}

function renderScenario(){return page('Scenario lab & digital twin','Model directional effects transparently. Scenarios are planning aids, not forecasts, and all assumptions remain visible.',`<div class="grid">${card('Community digital twin',`<form id="scenarioForm" class="formgrid"><div class="field"><label>Premises</label><input name="premises" type="number" value="10000"></div><div class="field"><label>Currently adequate connectivity %</label><input name="connected" type="number" min="0" max="100" value="70"></div><div class="field"><label>New infrastructure reaches % of current gap</label><input name="reach" type="number" min="0" max="100" value="80"></div><div class="field"><label>Affordability/adoption conversion % of newly reachable</label><input name="adopt" type="number" min="0" max="100" value="65"></div><div class="field"><label>Device readiness %</label><input name="devices" type="number" min="0" max="100" value="85"></div><div class="field"><label>Skills/service readiness %</label><input name="skills" type="number" min="0" max="100" value="80"></div><div class="span2"><button class="btn primary">Run simplified scenario</button></div></form><div id="scenarioResult"></div>`,'wide')}${card('Interpretation',`<p>The model multiplies explicit gating assumptions to approximate how many currently disconnected premises might convert to effective access.</p><p>It does <strong>not</strong> model causal effects on employment, health or education outcomes. Use domain-specific evidence for those questions.</p>`)}${card('Failure cascade exercise',`<div class="flow"><span>ISP outage</span><b>→</b><span>telehealth</span><b>+</b><span>remote work</span><b>+</b><span>school</span><b>→</b><span>backup link / public hub / offline procedure</span></div><p>Use shared tasks to assign mitigations to different domains.</p>`,'full')}</div>`)}

function renderFunding(){return page('Funding & program navigator','Current official program references are included as dated evidence. Status labels are intentionally conservative; always verify a funding window at the official page before acting.',`<div class="grid">${card('Program registry',`<div class="list">${state.texas.programs.map(p=>`<div class="item"><div class="meta"><span>${esc(p.domain)}</span><span>·</span><span>${esc(p.status)}</span></div><h3>${esc(p.name)}</h3><p>${esc(p.who)}</p><p class="small muted">${esc(p.action)}</p><a href="${p.url}" target="_blank" rel="noopener">Official program page ↗</a></div>`).join('')}</div>`,'wide')}${card('Grant-readiness packet',`<ul><li>defined project area and need</li><li>network/design concept and milestones</li><li>cost and sustainability assumptions</li><li>local support/partnerships</li><li>digital adoption/literacy plan where relevant</li><li>workforce/safety capacity</li><li>evidence and verification plan</li></ul><p class="small muted">BDO planning guidance should be consulted for program-specific application requirements.</p>`)}${card('No fabricated opportunities',`<p>If a program page says “future NOFAs,” this suite does not convert that into an “open” grant. Closed funding-year deadlines remain labeled closed/historical.</p>`,'full')}</div>`)}

function renderResearch(){const groups=[...new Set(state.texas.facts.map(f=>f.publisher))];return page('Research & government document library','A curated starting set of current and historical official sources. Follow each official link for the authoritative document, map, eligibility rule or deadline.',`<div class="toolbar"><input id="researchSearch" class="search" placeholder="Search sources, programs, publishers…"><select id="publisherFilter"><option value="">All publishers</option>${groups.map(g=>`<option>${esc(g)}</option>`).join('')}</select></div><div id="researchList" class="domainGrid" style="margin-top:1rem">${state.texas.facts.map(sourceCard).join('')}</div>`)}
function renderEvidence(){return page('Evidence registry & provenance','Keep source, publisher, dataset/document, geography, publication/retrieval date, limitations and evidence class attached to every consequential claim.',`<div class="grid">${card('Evidence classes',`<div class="list">${Object.entries(state.texas.evidenceScale).map(([k,v])=>`<div class="item"><span class="tag grade-${k}">${k}</span> ${esc(v)}</div>`).join('')}</div>`,'half')}${card('Provenance minimum',`<ul><li>source URL / identifier</li><li>publisher</li><li>dataset/document name</li><li>geography and population</li><li>publication + retrieval dates</li><li>update cadence where known</li><li>limitations / transformations</li><li>license/terms where relevant</li></ul>`,'half')}${card('Included official evidence',`<div class="domainGrid">${state.texas.facts.map(sourceCard).join('')}</div>`,'full')}</div>`)}

function renderAI(){const cap=AI.capability();return page('Local planning assistant / WebLLM','Optional in-browser AI uses WebGPU and the open-source WebLLM runtime. Models are downloaded separately and can be large; no model is bundled into this ZIP. A deterministic non-AI fallback is always available.',`<div class="grid">${card('Capability',`<div class="list"><div class="item">WebGPU: <strong>${cap.webgpu?'available':'not detected'}</strong></div><div class="item">Secure context: <strong>${cap.secure?'yes':'no'}</strong></div><div class="item">Online for initial model/runtime fetch: <strong>${cap.online?'yes':'no'}</strong></div></div><p class="small muted">WebLLM v0.2.85 is loaded from esm.run only after you request it. Model caching is handled by WebLLM/IndexedDB, not by this app shell's service worker.</p>`)}${card('Model loader',`<div class="field"><label>Model</label><select id="modelSelect"><option>Load model catalog…</option></select></div><div class="actions"><button class="btn" id="loadCatalog">Load catalog</button><button class="btn primary" id="loadModel">Load selected model</button><button class="btn" id="unloadModel">Unload</button></div><div id="aiProgress" class="small muted"></div>`,'half')}${card('Cross-domain prompt builder',`<form id="aiForm" class="formgrid"><div class="field"><label>Geography</label><input name="geography" value="Texas"></div><div class="field"><label>Stakeholders</label><input name="stakeholders" placeholder="county, library, clinic, school..."></div><div class="field span2"><label>Connectivity problem</label><textarea name="problem" required></textarea></div><div class="span2"><div class="matrix" id="aiDomains">${state.cross.domains.map(d=>`<button type="button" data-ai-domain="${d.id}">${d.icon} ${esc(d.name)}</button>`).join('')}</div></div><div class="span2 actions"><button class="btn" type="button" id="fallbackPlan">Generate deterministic plan</button><button class="btn primary" type="submit">Ask loaded local model</button></div></form>`,'wide')}${card('Output','<div id="aiOutput" class="codeish">No plan generated yet.</div>','full')}</div>`)}

function renderData(){return page('Data sovereignty, backup & sync','Local records remain in IndexedDB by default. The hosted app auto-joins the public collaboration commons on startup, but only records explicitly shared in the active room are synchronized. Trystero discovery may contact the selected signaling network; application collaboration data uses WebRTC between peers.',`<div class="grid">${card('Backup',`<div class="actions"><button class="btn primary" id="exportBackup">Export JSON backup</button><label class="btn">Import JSON<input id="importBackup" type="file" accept="application/json" hidden></label><button class="btn" id="inspectData">Inspect counts</button><button class="btn bad" id="resetData">Reset local records</button></div><pre id="dataInspect" class="codeish"></pre>`,'wide')}${card('Offline architecture',`<ul><li>App shell/resources: service-worker precache over HTTP(S).</li><li>User records: IndexedDB.</li><li>Small preferences: localStorage.</li><li>Peer state: local IndexedDB + room snapshot/event exchange.</li><li>WebLLM models: runtime-managed cache; not precached by this service worker.</li></ul><p><strong>file://:</strong> service workers and ES-module app behavior are not claimed. Use <code>standalone.html</code> for direct-file fallback.</p>`)}${card('Portable data rules',`<p>Backups use an explicit schema. Import validates the schema before writing. Destructive replacement requires confirmation.</p><p>The default public room auto-connects in hosted/online mode. Cross-device <em>record</em> sync still occurs only for records explicitly shared in the active room. Snapshots are room-scoped, and Internal/Sensitive records are not broadcast into the public commons.</p>`,'full')}</div>`)}

function renderAtlas(){return page('111-section requirement atlas','The original comprehensive specification is preserved verbatim by section inside the bundle and remains searchable as a requirements/audit reference.',`<div class="toolbar"><input id="atlasSearch" class="search" placeholder="Search all 111 requirements"><span id="atlasCount" class="tag">${state.requirements.length} sections</span></div><div id="atlasList" class="atlas">${atlasHtml(state.requirements)}</div>`)}
function atlasHtml(rows){return rows.map(x=>`<details><summary>${x.id}. ${esc(x.title)}</summary><div class="body">${esc(x.body)}</div></details>`).join('')}

function renderAbout(){return page('Architecture, privacy & integrity','A public-ready reference implementation for Texas connectivity and opportunity planning. It is designed to help people measure, coordinate and act without pretending that modeled data or collaboration demos are official government systems.',`<div class="grid">${card('Runtime architecture',`<ul><li>semantic HTML + CSS + ES modules</li><li>single central route registry</li><li>institution/family/business partner playbook + typed cross-domain handoffs</li><li>IndexedDB structured state</li><li>BroadcastChannel local multiplayer</li><li>Trystero 0.25.3 action-object API with Nostr/MQTT/BitTorrent/IPFS discovery + direct WebRTC multiplayer</li><li>automatic default public commons with room-scoped snapshots and privacy-class broadcast guard</li><li>optional shared room password + explicit TURN fallback configuration</li><li>installable PWA + versioned service worker</li><li>optional WebLLM dedicated worker</li><li>validated JSON backup</li><li>print/reduced-motion/high-contrast support</li></ul>`,'half')}${card('Zero-harm / anti-inversion',`<p>Designed to improve access, opportunity, education, health, resilience and digital autonomy.</p><p>Do not use it to surveil households, expose sensitive locations, exploit exclusion data, manipulate vulnerable users, bypass device protections or conceal uncertainty.</p>`,'half')}${card('Integrity',`<p>Release byte hashes are recorded in <code>integrity/SHA256SUMS.txt</code>. SHA-256 can verify byte integrity against a known hash; it does <strong>not</strong> establish authorship or provenance by itself.</p><p>Concept/system architecture attribution: <strong>Ricky Foster + Navi · Planetary Restoration Archive</strong>.</p>`,'half')}${card('Open-source attribution',`<p>Trystero: Dan Motzenbecker and contributors, MIT. The browser imports Trystero 0.25.3 strategy modules at runtime for decentralized discovery and WebRTC collaboration.</p><p>WebLLM: MLC community, Apache-2.0. The application only loads WebLLM when requested.</p><p>The optional legacy Node adapter uses the <code>ws</code> npm package (MIT) after <code>npm install</code>. It is not required for normal Trystero/WebRTC multiplayer. No third-party library source is copied into this repository.</p><p>Official-source links remain owned/licensed by their publishers.</p>`,'half')}</div>`)}

function view(){switch(state.route){case'overview':return renderOverview();case'diagnostics':return renderDiagnostics();case'broadband':return renderBroadband();case'affordability':return renderAffordability();case'devices':return renderDevices();case'skills':return renderSkills();case'opportunity':return renderOpportunity();case'partners':return renderPartners();case'education':return domainView('education');case'health':return domainView('health');case'workforce':return domainView('workforce');case'business':return domainView('business');case'libraries':return domainView('libraries');case'emergency':return renderEmergency();case'infrastructure':return renderInfrastructure();case'mapping':return renderMapping();case'regions':return renderRegions();case'projects':return renderProjects();case'collaboration':return renderCollaboration();case'guides':return renderGuides();case'scenario':return renderScenario();case'funding':return renderFunding();case'research':return renderResearch();case'evidence':return renderEvidence();case'ai':return renderAI();case'data':return renderData();case'atlas':return renderAtlas();case'about':return renderAbout();default:return renderOverview()}}

async function render(){state.route=currentRoute();markActive();$('#outlet').innerHTML=view();bindCommon();await bindRoute();updateHUD();updateCollabBadge()}
function bindCommon(){
 $$('[data-jump]').forEach(b=>b.onclick=()=>go(b.dataset.jump));
 $$('[data-domain]').forEach(b=>b.onclick=()=>{const map={education:'education',health:'health',workforce:'workforce',business:'business',libraries:'libraries',emergency:'emergency'};if(map[b.dataset.domain])go(map[b.dataset.domain]);else toast('This domain is represented in cross-domain project/scenario tools.')} );
 $$('[data-source]').forEach(b=>b.onclick=()=>{const f=state.texas.facts.find(x=>x.id===b.dataset.source);if(f)window.open(f.url,'_blank','noopener')});
 $$('[data-prefill-region]').forEach(b=>b.onclick=()=>{localStorage.setItem('txco.projectPrefill',`${b.dataset.prefillRegion} connectivity initiative`);go('projects')});
}

async function bindRoute(){
 if(state.route==='diagnostics')bindDiagnostics();
 if(state.route==='broadband')await bindBroadband();
 if(state.route==='affordability')bindAffordability();
 if(state.route==='devices')await bindDevices();
 if(state.route==='projects')await bindProjects();
 if(state.route==='collaboration')await bindCollaboration();
 if(state.route==='scenario')bindScenario();
 if(state.route==='infrastructure')bindInfrastructure();
 if(state.route==='research')bindResearch();
 if(state.route==='ai')bindAI();
 if(state.route==='data')bindData();
 if(state.route==='atlas')bindAtlas();
}
function bindDiagnostics(){
 $('#diagForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const cost=+o.cost,income=+o.income,down=+o.down,adv=+o.advDown,up=+o.up,lat=+o.latency,out=+o.outages;const burden=income?cost/income*100:0;const issues=[];if(adv&&down<adv*.5)issues.push('Measured download is under 50% of advertised rate in this observation; repeat under controlled wired/Wi-Fi conditions before attributing cause.');if(up<10)issues.push('Upload may constrain simultaneous video calls, large uploads or remote-work/telehealth workflows.');if(lat>100)issues.push('Latency is high enough to merit investigation for interactive uses.');if(out>=3)issues.push('Frequent outages indicate a reliability/resilience problem worth logging by date/time.');if(burden>=5)issues.push('Internet cost is a material share of entered monthly income; compare plan/fee/public-access options.');if(o.device!=='yes')issues.push('Device access appears to be a bottleneck independent of service availability.');if(o.skills!=='high')issues.push('Digital-skills/support capacity is part of the access gap.');if(o.access==='yes')issues.push('Accessibility requirements should be included in service/device/platform selection.');$('#diagResult').innerHTML=`<div class="callout"><strong>Broadband burden:</strong> ${burden.toFixed(1)}% · <strong>Observed/advertised download:</strong> ${adv?Math.round(down/adv*100):'n/a'}%</div><div class="list">${issues.map(x=>`<div class="item">${esc(x)}</div>`).join('')||'<div class="item">No obvious bottleneck triggered by these simple thresholds. Continue with repeated measurements and task-specific needs.</div>'}</div>`};
 $('#bwForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const down=+o.hd*5+ +o.k4*25+ +o.calls*4+ +o.gaming*25+ +o.classes*4+ +o.uploads*10;const up=+o.calls*4+ +o.gaming*5+ +o.classes*3+ +o.uploads*20;$('#bwResult').innerHTML=`<div class="callout"><strong>Approximate simultaneous target:</strong> ${fmt(down)} Mbps down / ${fmt(up)} Mbps up before headroom.</div><p class="small muted">Activity assumptions are rough planning values; codecs/services vary. Add headroom for Wi-Fi, bursts and additional users.</p>`};
 $('#powerForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target)),load=+o.router+ +o.modem+ +o.other,hours=load?+o.wh*(+o.eff/100)/load:0;$('#powerResult').innerHTML=`<div class="callout"><strong>Approximate runtime:</strong> ${hours.toFixed(1)} hours at ${load.toFixed(1)} W.</div><p class="small muted">Battery inverter/DC conversion, battery aging, temperature and ISP upstream power may reduce real continuity.</p>`}
}
async function bindBroadband(){
 $('#speedForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));await DB.put('speedTests',{id:DB.uid('speed'),...o,down:+o.down,up:+o.up,latency:+o.latency,createdAt:DB.now(),modifiedAt:DB.now(),clientId:collab.clientId});e.target.reset();toast('Speed observation saved locally');await refreshSpeeds()};
 $('#outageForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));await DB.put('outages',{id:DB.uid('out'),...o,minutes:+o.minutes,createdAt:DB.now(),modifiedAt:DB.now(),clientId:collab.clientId});toast('Reliability event saved');e.target.reset()};
 $('#speedCsv').onclick=async()=>{const rows=await DB.all('speedTests');csvDownload('speed-tests.csv',rows)};await refreshSpeeds();
}
async function refreshSpeeds(){const rows=(await DB.all('speedTests')).sort((a,b)=>Date.parse(a.createdAt)-Date.parse(b.createdAt));const list=$('#speedList');if(list)list.innerHTML=rows.slice(-8).reverse().map(r=>`<div class="item"><strong>${esc(r.provider)}</strong> · ${fmt(r.down)}/${fmt(r.up)} Mbps · ${fmt(r.latency)} ms<div class="small muted">${new Date(r.createdAt).toLocaleString()} · ${esc(r.connection)} · ${esc(r.place)}</div></div>`).join('')||'<p class="muted">No local observations yet.</p>';drawSpeed(rows.slice(-24))}
function drawSpeed(rows){const c=$('#speedChart');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const style=getComputedStyle(document.documentElement),line=style.getPropertyValue('--line'),ink=style.getPropertyValue('--ink'),accent=style.getPropertyValue('--accent');ctx.strokeStyle=line;ctx.fillStyle=ink;ctx.font='12px system-ui';for(let i=0;i<5;i++){const y=20+i*(h-45)/4;ctx.beginPath();ctx.moveTo(45,y);ctx.lineTo(w-15,y);ctx.stroke()}if(!rows.length){ctx.fillText('No speed observations yet',55,45);return}const max=Math.max(10,...rows.flatMap(r=>[+r.down,+r.up]));const x=i=>45+i*(w-70)/Math.max(1,rows.length-1),y=v=>h-25-(+v/max)*(h-55);ctx.strokeStyle=accent;ctx.lineWidth=3;ctx.beginPath();rows.forEach((r,i)=>i?ctx.lineTo(x(i),y(r.down)):ctx.moveTo(x(i),y(r.down)));ctx.stroke();ctx.setLineDash([6,4]);ctx.beginPath();rows.forEach((r,i)=>i?ctx.lineTo(x(i),y(r.up)):ctx.moveTo(x(i),y(r.up)));ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=ink;ctx.fillText(`max ${max.toFixed(0)} Mbps · solid=down, dashed=up`,50,15)}
function bindAffordability(){$('#affForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const burden=+o.income?+o.internet/+o.income*100:0,annual=(+o.internet+ +o.mobile+ +o.software)*12+ +o.devices+ +o.repairs;$('#affResult').innerHTML=`<div class="callout"><strong>Broadband burden:</strong> ${burden.toFixed(1)}%<br><strong>Total entered digital-access cost:</strong> ${money(annual)}/year</div>`}}
async function bindDevices(){$('#deviceForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));await DB.put('devices',{id:DB.uid('dev'),...o,createdAt:DB.now(),modifiedAt:DB.now(),clientId:collab.clientId});e.target.reset();toast('Device saved');refreshDevices()};await refreshDevices()}
async function refreshDevices(){const el=$('#deviceList');if(!el)return;const rows=await DB.all('devices');el.innerHTML=rows.map(r=>`<div class="item"><strong>${esc(r.name)}</strong> · ${esc(r.type)}<div class="small muted">OS ${esc(r.os||'—')} · battery ${esc(r.battery||'—')} · storage ${esc(r.storage||'—')} · ${esc(r.use||'')}</div><button class="btn small" data-del-device="${r.id}">Delete</button></div>`).join('')||'<p class="muted">No devices saved.</p>';$$('[data-del-device]').forEach(b=>b.onclick=async()=>{await DB.del('devices',b.dataset.delDevice);refreshDevices()})}
async function bindProjects(){const selected=new Set();const pre=localStorage.getItem('txco.projectPrefill')||'';if(pre){$('#projectForm [name=title]').value=pre;localStorage.removeItem('txco.projectPrefill')}$$('[data-domain-tag]').forEach(b=>b.onclick=()=>{b.classList.toggle('selected');b.classList.contains('selected')?selected.add(b.dataset.domainTag):selected.delete(b.dataset.domainTag)});$('#projectForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const p={id:DB.uid('project'),...o,capital:+o.capital||0,operating:+o.operating||0,domains:[...selected],createdAt:DB.now(),modifiedAt:DB.now(),clientId:collab.clientId,owner:collab.name};const result=await collab.broadcast('project',p);toast(result.localOnly?'Project saved locally — privacy class blocks public-room broadcast':'Project saved/shared to active room');e.target.reset();selected.clear();$$('[data-domain-tag]').forEach(b=>b.classList.remove('selected'));refreshProjects()};await refreshProjects()}
async function refreshProjects(){const el=$('#projectList');if(!el)return;const rows=(await DB.all('projects')).sort((a,b)=>Date.parse(b.modifiedAt)-Date.parse(a.modifiedAt));el.innerHTML=rows.map(p=>`<div class="item"><div class="meta"><span>${esc(p.status)}</span><span>·</span><span>${esc(p.geography||'Texas')}</span><span>·</span><span>${esc(p.owner||'local')}</span></div><h3>${esc(p.title)}</h3><p>${esc(p.problem)}</p><div class="chips">${(p.domains||[]).map(x=>`<span class="tag">${esc(x)}</span>`).join('')}</div><p class="small muted">${p.capital?money(p.capital)+' capital · ':''}${p.timeline?esc(p.timeline):''}</p></div>`).join('')||'<p class="muted">No projects yet.</p>'}
async function bindCollaboration(){
 renderPresence();
 $('#roomForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));if(o.room===DEFAULT_PUBLIC_ROOM&&o.password){toast('The default public room is passwordless. Choose a custom room ID for password-protected collaboration.');return}collab.configure(o);try{let turnConfig=null;if(o.turnJson?.trim()){turnConfig=JSON.parse(o.turnJson);if(!Array.isArray(turnConfig))throw new Error('TURN configuration must be a JSON array.')}await collab.connectTrystero({strategy:o.strategy,password:o.password,turnConfig});toast(o.room===DEFAULT_PUBLIC_ROOM?'Public P2P commons active':'Selected decentralized P2P room active')}catch(err){console.error(err);toast(`P2P connection failed: ${err.message}`);state.collabStatus={mode:'p2p',connected:false,room:collab.room,publicRoom:collab.room===DEFAULT_PUBLIC_ROOM};updateCollabBadge()}};
 $('#rejoinPublic').onclick=async()=>{const f=$('#roomForm');collab.configure({name:f.name.value,role:f.role.value});f.room.value=DEFAULT_PUBLIC_ROOM;f.strategy.value='nostr';f.password.value='';f.turnJson.value='';const result=await collab.startPublic({strategy:'nostr'});toast(result.mode==='p2p'?'Default public P2P commons active':'Public commons using same-device fallback')};
 $('#copyRoom').onclick=async()=>{const f=$('#roomForm');const text=JSON.stringify({room:f.room.value,strategy:f.strategy.value,app:'Texas Connectivity & Opportunity OS v5',publicRoom:f.room.value===DEFAULT_PUBLIC_ROOM,identityWarning:'Display names, roles and peer identifiers are self-asserted and unverified.'},null,2);try{await navigator.clipboard.writeText(text);toast('Non-secret room settings copied')}catch{dl('txco-room-settings.json',text,'application/json')}};
 $('#localRoom').onclick=async()=>{const f=$('#roomForm');collab.configure({name:f.name.value,role:f.role.value,room:f.room.value});await collab.startLocal();toast('Same-device BroadcastChannel commons active')};
 $('#disconnectRoom').onclick=()=>{collab.stop();state.collabStatus={mode:'offline',connected:false,room:collab.room,publicRoom:collab.room===DEFAULT_PUBLIC_ROOM};render();toast('Left collaboration room; reload or use Rejoin default public room to reconnect')};
 $('#taskForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));await collab.broadcast('task',{id:DB.uid('task'),...o,createdAt:DB.now(),modifiedAt:DB.now()});e.target.reset();refreshCollabLists()};
 $('#decisionForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));await collab.broadcast('decision',{id:DB.uid('decision'),...o,createdAt:DB.now(),modifiedAt:DB.now()});e.target.reset();refreshCollabLists()};
 $('#commentForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));await collab.broadcast('comment',{id:DB.uid('comment'),text:o.text,author:collab.name,role:collab.role,createdAt:DB.now(),modifiedAt:DB.now()});e.target.reset();refreshCollabLists()};
 $('#handoffForm').onsubmit=async e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const result=await collab.broadcast('handoff',{id:DB.uid('handoff'),...o,createdAt:DB.now(),modifiedAt:DB.now(),createdBy:collab.name});toast(result.localOnly?'Handoff saved locally — not broadcast to the public commons':'Handoff shared to active room');e.target.reset();refreshCollabLists()};
 await refreshCollabLists();
}
async function refreshCollabLists(){
 const visible=r=>r?.collaborationRoom===collab.room||r?.localOnly===true;
 const tasks=(await DB.all('tasks')).filter(visible),dec=(await DB.all('decisions')).filter(visible),comments=(await DB.all('comments')).filter(visible).sort((a,b)=>Date.parse(b.createdAt)-Date.parse(a.createdAt)),handoffs=(await DB.all('handoffs')).filter(visible).sort((a,b)=>Date.parse(b.modifiedAt)-Date.parse(a.modifiedAt));
 const board=$('#taskBoard');
 if(board){const lanes=['Backlog','Doing','Blocked','Done'];board.innerHTML=lanes.map(l=>`<section class="lane"><h3>${l}</h3>${tasks.filter(t=>t.status===l).map(t=>`<div class="task"><strong>${esc(t.title)}</strong><div class="small muted">${esc(t.domain)} · ${esc(t.assignee||'unassigned')} ${t.due?'· '+esc(t.due):''}${t.localOnly?' · LOCAL ONLY':''}</div><select data-task-status="${t.id}">${lanes.map(x=>`<option ${x===t.status?'selected':''}>${x}</option>`).join('')}</select></div>`).join('')}</section>`).join('');$$('[data-task-status]').forEach(s=>s.onchange=async()=>{const t=tasks.find(x=>x.id===s.dataset.taskStatus);await collab.broadcast('task',{...t,status:s.value,modifiedAt:DB.now()});refreshCollabLists()})}
 const de=$('#decisionList');if(de)de.innerHTML=dec.sort((a,b)=>Date.parse(b.modifiedAt)-Date.parse(a.modifiedAt)).map(d=>`<div class="item"><strong>${esc(d.title)}</strong><div class="meta"><span>${esc(d.status)}</span>${d.localOnly?'<span>· LOCAL ONLY</span>':''}</div><p>${esc(d.rationale)}</p></div>`).join('')||'<p class="muted">No decisions in this room yet.</p>';
 const ce=$('#commentList');if(ce)ce.innerHTML=comments.slice(0,20).map(c=>`<div class="item"><strong>${esc(c.author||'Member')}</strong> <span class="small muted">${new Date(c.createdAt).toLocaleString()}${c.localOnly?' · LOCAL ONLY':''}</span><p>${esc(c.text)}</p></div>`).join('')||'<p class="muted">No coordination notes in this room yet.</p>';
 const he=$('#handoffList');if(he){he.innerHTML=handoffs.map(h=>`<div class="item"><div class="meta"><span>${esc(h.fromDomain)} → ${esc(h.toDomain)}</span><span>·</span><span>${esc(h.status)}</span>${h.due?`<span>· due ${esc(h.due)}</span>`:''}${h.localOnly?'<span>· LOCAL ONLY</span>':''}</div><strong>${esc(h.request)}</strong><p class="small muted">Owner: ${esc(h.owner||'unassigned')} · Privacy: ${esc(h.privacyClass||'Public')} ${h.evidence?'· Evidence: '+esc(h.evidence):''}</p><select data-handoff-status="${h.id}"><option ${h.status==='Requested'?'selected':''}>Requested</option><option ${h.status==='Acknowledged'?'selected':''}>Acknowledged</option><option ${h.status==='In progress'?'selected':''}>In progress</option><option ${h.status==='Blocked'?'selected':''}>Blocked</option><option ${h.status==='Completed'?'selected':''}>Completed</option><option ${h.status==='Verified'?'selected':''}>Verified</option></select></div>`).join('')||'<p class="muted">No handoffs in this room yet.</p>';$$('[data-handoff-status]').forEach(s=>s.onchange=async()=>{const h=handoffs.find(x=>x.id===s.dataset.handoffStatus);const result=await collab.broadcast('handoff',{...h,status:s.value,modifiedAt:DB.now()});if(result.localOnly)toast('Updated locally only');refreshCollabLists()})}
}
function bindScenario(){$('#scenarioForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target));const premises=+o.premises,current=premises*(+o.connected/100),gap=premises-current,newReach=gap*(+o.reach/100),effective=newReach*(+o.adopt/100)*(+o.devices/100)*(+o.skills/100),after=current+effective;$('#scenarioResult').innerHTML=`<div class="callout"><strong>Currently adequate (input):</strong> ${Math.round(current).toLocaleString()} premises<br><strong>Newly reached by infrastructure:</strong> ${Math.round(newReach).toLocaleString()}<br><strong>Modeled effective-access conversions after affordability/adoption + device + skills gates:</strong> ${Math.round(effective).toLocaleString()}<br><strong>Modeled total effective access:</strong> ${Math.round(after).toLocaleString()} (${(after/premises*100).toFixed(1)}%)</div>`}}
function bindInfrastructure(){$('#infraForm').onsubmit=e=>{e.preventDefault();const o=Object.fromEntries(new FormData(e.target)),base=+o.miles*+o.mileCost+ +o.premises*+o.dropCost+ +o.backhaul,total=base*(1+ +o.cont/100);$('#infraResult').innerHTML=`<div class="callout"><strong>Simplified planning total:</strong> ${money(total)}<br><strong>Approx. / premise:</strong> ${money(total/Math.max(1,+o.premises))}</div>`}}
function bindResearch(){const run=()=>{const q=$('#researchSearch').value.toLowerCase(),p=$('#publisherFilter').value;const rows=state.texas.facts.filter(f=>(!q||JSON.stringify(f).toLowerCase().includes(q))&&(!p||f.publisher===p));$('#researchList').innerHTML=rows.map(sourceCard).join('')||'<p class="muted">No source matches.</p>'};$('#researchSearch').oninput=run;$('#publisherFilter').onchange=run}
function bindAI(){let selected=new Set();$$('[data-ai-domain]').forEach(b=>b.onclick=()=>{b.classList.toggle('selected');b.classList.contains('selected')?selected.add(b.dataset.aiDomain):selected.delete(b.dataset.aiDomain)});$('#loadCatalog').onclick=async()=>{try{$('#aiProgress').textContent='Loading WebLLM runtime/catalog…';const ms=await AI.models();$('#modelSelect').innerHTML=ms.map(m=>`<option value="${esc(m.id)}">${esc(m.name)}</option>`).join('');$('#aiProgress').textContent=`${ms.length} prebuilt model records available. Choose a model appropriate for your device memory.`}catch(e){$('#aiProgress').textContent='Could not load WebLLM catalog: '+e.message}};$('#loadModel').onclick=async()=>{const id=$('#modelSelect').value;if(!id||id.includes('catalog'))return;try{$('#aiProgress').textContent='Initializing…';await AI.loadModel(id,p=>{$('#aiProgress').textContent=p.text||`${Math.round((p.progress||0)*100)}%`});$('#aiProgress').textContent='Model loaded locally.'}catch(e){$('#aiProgress').textContent='Model load failed: '+e.message}};$('#unloadModel').onclick=async()=>{await AI.unload();$('#aiProgress').textContent='Model unloaded.'};const input=()=>{const f=$('#aiForm'),o=Object.fromEntries(new FormData(f));return {...o,domains:[...selected]}};$('#fallbackPlan').onclick=()=>{$('#aiOutput').textContent=AI.fallbackPlan(input())};$('#aiForm').onsubmit=async e=>{e.preventDefault();const i=input(),sources=state.texas.facts.filter(f=>['bead-summary','boot','digital-opportunity','fcc-map','rhcf','erate','workforce'].includes(f.id)).map(f=>`${f.title}: ${f.value} (${f.publisher}, ${f.date})`).join('\n');const system=`You are a neutral Texas connectivity planning assistant running locally in the user's browser. Distinguish sourced facts from assumptions and modeled scenarios. Do not invent grants, deadlines, coverage or provider performance. Treat cross-domain benefits as pathways, not guaranteed causal outcomes. Current curated source notes:\n${sources}`;try{$('#aiOutput').textContent='Generating locally…';const out=await AI.ask([{role:'system',content:system},{role:'user',content:`Create a cross-domain plan for ${i.geography}. Problem: ${i.problem}. Stakeholders: ${i.stakeholders}. Domains: ${i.domains.join(', ')}. Include verification steps, owners, dependencies, resilience, accessibility, privacy, 30/60/90-day actions and uncertainty.`}]);$('#aiOutput').textContent=out}catch(err){$('#aiOutput').textContent='Local model unavailable: '+err.message+'\n\n'+AI.fallbackPlan(i)}}}
function bindData(){$('#exportBackup').onclick=async()=>dl(`tx-connectivity-backup-${new Date().toISOString().slice(0,10)}.json`,JSON.stringify(await DB.exportBackup(),null,2),'application/json');$('#importBackup').onchange=async e=>{const f=e.target.files?.[0];if(!f)return;try{if(f.size>10*1024*1024)throw new Error('Backup exceeds the 10 MB import limit');const p=JSON.parse(await f.text());const replace=confirm('Replace existing local records? OK = replace, Cancel = merge.');const result=await DB.importBackup(p,{replace});toast(`Backup imported · ${result.records} records`)}catch(err){alert('Import failed: '+err.message)}finally{e.target.value=''}};$('#inspectData').onclick=async()=>{const out={};for(const s of DB.STORES)out[s]=await DB.count(s);$('#dataInspect').textContent=JSON.stringify(out,null,2)};$('#resetData').onclick=async()=>{if(!confirm('Delete all local project/tool/collaboration records? Export a backup first if needed.'))return;for(const s of DB.STORES)await DB.clear(s);toast('Local records reset');updateHUD()}}
function bindAtlas(){$('#atlasSearch').oninput=e=>{const q=e.target.value.toLowerCase();const rows=state.requirements.filter(x=>!q||(`${x.id} ${x.title} ${x.body}`).toLowerCase().includes(q));$('#atlasCount').textContent=`${rows.length} sections`;$('#atlasList').innerHTML=atlasHtml(rows)}}
function csvDownload(name,rows){if(!rows.length){toast('Nothing to export');return}const keys=[...new Set(rows.flatMap(r=>Object.keys(r)))],q=v=>'"'+String(typeof v==='object'?JSON.stringify(v):v??'').replaceAll('"','""')+'"';dl(name,[keys.map(q).join(','),...rows.map(r=>keys.map(k=>q(r[k])).join(','))].join('\n'),'text/csv')}

function openSearch(){const m=$('#searchModal');m.hidden=false;const i=$('#globalSearch');i.value='';i.focus();renderSearch('')}
function renderSearch(q){q=q.toLowerCase().trim();const rs=ROUTES.filter(r=>!q||`${r.label} ${r.group}`.toLowerCase().includes(q)).slice(0,12),facts=state.texas.facts.filter(f=>q&&JSON.stringify(f).toLowerCase().includes(q)).slice(0,8),req=state.requirements.filter(x=>q&&`${x.title} ${x.body}`.toLowerCase().includes(q)).slice(0,8);$('#searchResults').innerHTML=[...rs.map(r=>`<button class="navlink" data-search-route="${r.id}">${r.icon} ${esc(r.label)} <span class="muted small">${esc(r.group)}</span></button>`),...facts.map(f=>`<button class="navlink" data-search-source="${f.id}">✓ ${esc(f.title)}</button>`),...req.map(x=>`<button class="navlink" data-search-atlas="${x.id}">☷ ${x.id}. ${esc(x.title)}</button>`)].join('')||'<p class="muted">No matches.</p>';$$('[data-search-route]').forEach(b=>b.onclick=()=>{$('#searchModal').hidden=true;go(b.dataset.searchRoute)});$$('[data-search-source]').forEach(b=>b.onclick=()=>{$('#searchModal').hidden=true;go('research');setTimeout(()=>{$('#researchSearch').value=state.texas.facts.find(f=>f.id===b.dataset.searchSource)?.title||'';$('#researchSearch').dispatchEvent(new Event('input'))},60)});$$('[data-search-atlas]').forEach(b=>b.onclick=()=>{$('#searchModal').hidden=true;go('atlas');setTimeout(()=>{$('#atlasSearch').value=b.dataset.searchAtlas;$('#atlasSearch').dispatchEvent(new Event('input'))},60)})}
function openSettings(){const p=$('#settings');p.hidden=false;p.innerHTML=`<h2>Settings</h2><div class="settingsRow"><span>Theme</span><select id="setTheme"><option value="dark">Dark</option><option value="light">Light</option></select></div><div class="settingsRow"><span>High contrast</span><input id="setContrast" type="checkbox"></div><div class="settingsRow"><span>Motion</span><input id="setMotion" type="checkbox"></div><div class="settingsRow"><span>Text size</span><input id="setFont" type="range" min=".9" max="1.35" step=".05"></div><div class="settingsRow"><span>Opportunity HUD</span><input id="setHud" type="checkbox"></div><p class="small muted">No analytics or telemetry are embedded. Collaboration and WebLLM network access are user-triggered.</p><div class="actions"><button class="btn" id="closeSettings">Close</button><button class="btn" data-route-settings="data">Data controls</button></div>`;$('#setTheme').value=state.prefs.theme;$('#setContrast').checked=state.prefs.contrast;$('#setMotion').checked=state.prefs.motion;$('#setFont').value=state.prefs.font;$('#setHud').checked=state.prefs.hud;$('#setTheme').onchange=e=>{state.prefs.theme=e.target.value;savePrefs()};$('#setContrast').onchange=e=>{state.prefs.contrast=e.target.checked;savePrefs()};$('#setMotion').onchange=e=>{state.prefs.motion=e.target.checked;savePrefs()};$('#setFont').oninput=e=>{state.prefs.font=+e.target.value;savePrefs()};$('#setHud').onchange=e=>{state.prefs.hud=e.target.checked;savePrefs()};$('#closeSettings').onclick=()=>p.hidden=true;$('[data-route-settings]').onclick=()=>{p.hidden=true;go('data')}}
async function updateHUD(){const [projects,tasks,devices,speeds,handoffs]=await Promise.all(['projects','tasks','devices','speedTests','handoffs'].map(DB.count));$('#hudProjects').textContent=projects;$('#hudTasks').textContent=tasks;$('#hudEvidence').textContent=state.texas?.facts?.length||0;$('#hudLine').textContent=`${devices} devices · ${speeds} speed observations · ${handoffs} cross-domain handoffs`}
function updateNetwork(){const on=navigator.onLine;$('#netDot').classList.toggle('on',on);$('#netText').textContent=on?'Online':'Offline'}
function updateCollabBadge(){const el=$('#collabText');if(!el)return;el.textContent=state.collabStatus.connected?`${state.collabStatus.mode}${state.collabStatus.publicRoom?' · PUBLIC':''} · ${Math.max(1,state.presence.length)} online`:'Solo/local';$('#collabDot').classList.toggle('on',state.collabStatus.connected)}
function bindShell(){$('#menuBtn').onclick=()=>{document.body.classList.add('drawer-open');$('#drawerScrim').hidden=false};$('#drawerScrim').onclick=closeDrawer;$('#searchBtn').onclick=openSearch;$('#closeSearch').onclick=()=>$('#searchModal').hidden=true;$('#globalSearch').oninput=e=>renderSearch(e.target.value);$('#settingsBtn').onclick=openSettings;const skip=$('#skipSplash');if(skip)skip.onclick=()=>$('#splash').classList.add('hide');addEventListener('hashchange',render);addEventListener('online',()=>{updateNetwork();if(state.route)render()});addEventListener('offline',()=>{updateNetwork();if(state.route)render()});addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch()}if(e.key==='Escape'){closeDrawer();$('#searchModal').hidden=true;$('#settings').hidden=true}})}
async function registerSW(){if('serviceWorker'in navigator&&location.protocol.startsWith('http')){try{await navigator.serviceWorker.register('./sw.js')}catch(e){console.warn('Service worker registration failed',e)}}}
async function startDefaultPublicCommons(){if(location.protocol==='file:'){await collab.startLocal();return}const result=await collab.startPublic({strategy:'nostr'});if(result?.mode!=='p2p')console.warn('Public P2P commons unavailable; BroadcastChannel fallback active.',result?.reason||'unknown reason')}

(async()=>{try{await loadData();await DB.openDB();applyPrefs();renderNav();bindShell();updateNetwork();await render();await registerSW();startDefaultPublicCommons().catch(e=>{console.warn('Automatic public commons connection failed',e);state.collabStatus={mode:'offline',connected:false,publicRoom:true,room:DEFAULT_PUBLIC_ROOM};updateCollabBadge()})}catch(e){console.error(e);$('#outlet').innerHTML=`<section class="hero"><h1>Initialization error</h1><p>${esc(e.message)}</p><p>Run this bundle through an HTTP server so ES modules and local JSON can load. For direct <code>file://</code> use, open <code>standalone.html</code>.</p></section>`}finally{setTimeout(()=>$('#splash').classList.add('hide'),state.prefs.motion?1250:0)}})();
